input.content:
/* ================= STAGE 4 : EVIDENCE BOARD ================= */
.screen-board{
  background:
    radial-gradient(ellipse at 50% 38%,rgba(92,69,43,.16),transparent 64%),
    linear-gradient(180deg,#0e0b08,#060504);
}
.board-hud{align-items:flex-start}
.board-body{
  flex:1;min-height:0;display:flex;flex-direction:column;gap:5px;
  margin-top:8px;padding:9px 10px 10px;overflow:hidden;position:relative;
  border:1px solid rgba(201,161,94,.2);
  background:
    radial-gradient(circle at 80% 10%,rgba(155,110,63,.14),transparent 40%),
    radial-gradient(circle at 12% 74%,rgba(103,72,41,.13),transparent 45%),
    repeating-radial-gradient(circle at 33% 27%,rgba(196,155,104,.055) 0 1px,transparent 1px 4px),
    repeating-linear-gradient(8deg,rgba(0,0,0,.08) 0 2px,transparent 2px 7px),
    linear-gradient(145deg,#2d2117,#1d150f 65%,#17110c);
  box-shadow:inset 0 0 60px rgba(0,0,0,.78),0 14px 40px rgba(0,0,0,.4);
}
.board-body::before{
  content:"";position:absolute;inset:5px;border:1px solid rgba(233,221,196,.045);pointer-events:none;
}
.board-victim{display:flex;align-items:baseline;gap:7px;min-width:0;padding:0 2px 4px;border-bottom:1px solid rgba(233,221,196,.1);white-space:nowrap;z-index:1}
.board-victim span{font-size:6px;letter-spacing:.23em;color:var(--gold);flex-shrink:0}
.board-victim b{font-family:var(--serif);font-size:13px;font-weight:900;color:var(--paper);letter-spacing:.01em;overflow:hidden;text-overflow:ellipsis}
.board-victim i{font-family:var(--type);font-size:8px;color:var(--paper-faint);font-style:normal;overflow:hidden;text-overflow:ellipsis}
.section-head{
  display:flex;justify-content:space-between;align-items:center;gap:8px;z-index:1;
  padding:2px 1px 0;font-size:6.5px;font-weight:500;letter-spacing:.22em;color:var(--paper-faint);text-transform:uppercase;line-height:1;
}
.section-head span:last-child{color:var(--gold);letter-spacing:.16em}
.suspects-head{margin-top:1px}
.clue-list{display:flex;flex-direction:column;gap:4px;min-height:0;z-index:1}
.clue-row{
  position:relative;display:grid;grid-template-columns:19px 1fr;gap:7px;align-items:center;
  padding:6px 24px 6px 8px;color:#211910;
  background:
    repeating-linear-gradient(1deg,rgba(80,55,30,.035) 0 1px,transparent 1px 3px),
    linear-gradient(180deg,#e7d9bd,#d0bd99);
  border:1px solid rgba(90,65,35,.45);
  box-shadow:0 2px 5px rgba(0,0,0,.4),inset 0 1px 0 rgba(255,255,255,.3);
  transform:rotate(var(--tilt,0deg));flex-shrink:0;
}
.clue-row::after{
  content:"";position:absolute;right:7px;top:5px;width:7px;height:7px;border-radius:50%;
  background:radial-gradient(circle at 35% 30%,#d88672,#7c241f 52%,#3e0d0a);
  box-shadow:0 1px 2px rgba(0,0,0,.4);opacity:.9;
}
.clue-row .num{
  font-family:var(--serif);font-size:17px;font-weight:900;line-height:1;color:#7e5e36;opacity:.65;
  text-align:center;border-right:1px solid rgba(70,48,24,.18);
}
.clue-body{min-width:0}
.clue-meta-mini{display:flex;align-items:baseline;gap:6px;font-size:5.8px;font-weight:600;letter-spacing:.17em;text-transform:uppercase;color:#775d3b;line-height:1.2}
.clue-meta-mini b{color:#302315;font-weight:600}
.gun-flag{display:none;margin-left:auto;color:#7d241f;font-size:5.6px;letter-spacing:.14em}
.clue-row.is-gun{border-color:#8d352c;background:linear-gradient(180deg,#e9d5b5,#d6bb92)}
.clue-row.is-gun .gun-flag{display:inline-block}
.clue-txt{
  margin-top:3px;font-family:var(--type);font-size:clamp(8.3px,1.17vh,9.8px);
  line-height:1.34;color:#211910;letter-spacing:-.005em;
  display:-webkit-box;-webkit-line-clamp:3;-webkit-box-orient:vertical;overflow:hidden;
}
.clue-row.locked{
  background:repeating-linear-gradient(125deg,rgba(233,221,196,.035) 0 5px,rgba(0,0,0,.06) 5px 11px);
  border:1px dashed rgba(233,221,196,.18);color:var(--paper-faint);box-shadow:none;
}
.clue-row.locked::after{display:none}
.clue-row.locked .num{color:var(--paper-faint);opacity:.4}
.clue-row.locked .clue-txt{font-family:var(--ui);font-size:7px;letter-spacing:.18em;color:rgba(233,221,196,.3);text-transform:uppercase;line-height:1.4}
.clue-row.locked .clue-meta-mini{color:rgba(233,221,196,.25)}
.clue-row.locked .clue-meta-mini b{color:rgba(233,221,196,.4)}
.suspect-list{display:flex;flex-direction:column;gap:4px;min-height:0;z-index:1}
.suspect-row{
  display:flex;align-items:center;gap:8px;padding:5px 7px;flex-shrink:0;min-height:0;
  background:linear-gradient(100deg,rgba(32,25,19,.92),rgba(15,12,9,.88));
  border:1px solid rgba(233,221,196,.12);box-shadow:0 2px 8px rgba(0,0,0,.25);
}
.mugshot{
  position:relative;width:34px;height:44px;flex:0 0 34px;overflow:hidden;color:#14110e;
  background:
    linear-gradient(110deg,rgba(255,255,255,.14),transparent 45%),
    repeating-linear-gradient(0deg,transparent 0 6px,rgba(0,0,0,.22) 6px 8px),
    linear-gradient(145deg,#998d77,#5b5245 58%,#332d26);
  border:1px solid rgba(233,221,196,.21);
}
.mugshot::after{content:"";position:absolute;inset:0;background:radial-gradient(ellipse at 50% 34%,transparent 15%,rgba(0,0,0,.25) 100%)}
.mugshot svg{position:absolute;left:50%;bottom:-2px;width:88%;height:88%;transform:translateX(-50%)}
.sus-content{flex:1;min-width:0}
.sus-top{display:flex;align-items:baseline;gap:7px;min-width:0}
.sus-name{font-family:var(--serif);font-size:clamp(12px,1.75vh,14.5px);font-weight:900;line-height:1;color:var(--paper);letter-spacing:-.01em;white-space:nowrap}
.sus-role{font-size:6px;letter-spacing:.14em;color:var(--gold);text-transform:uppercase;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.sus-line{display:flex;gap:4px;margin-top:3.5px;font-size:clamp(7px,1.05vh,8.8px);line-height:1.35;color:var(--paper-dim);min-width:0}
.sus-line b{font-size:5.6px;letter-spacing:.13em;color:var(--paper-faint);font-weight:500;flex:0 0 auto;padding-top:1.5px}
.sus-line span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;font-family:var(--type)}
.board-actions{flex-shrink:0;display:grid;grid-template-columns:1.15fr 1fr;gap:7px;margin-top:8px}
.board-actions .btn{min-height:48px;font-size:8.6px;letter-spacing:.13em;padding:0 8px}
.board-actions .btn-primary{font-size:9px}
.screen-board.is-active .clue-row{animation:pinIn .4s both;animation-delay:calc(var(--i,0) * .06s)}
.screen-board.is-active .suspect-row{animation:pinIn .4s both;animation-delay:calc(.2s + var(--i,0) * .06s)}
@keyframes pinIn{from{opacity:0;transform:translateY(-5px) rotate(var(--tilt,0deg))}to{opacity:1;transform:translateY(0) rotate(var(--tilt,0deg))}}

/* ================= ACCUSATION ================= */
.screen-accuse{background:radial-gradient(ellipse at 50% 24%,rgba(106,77,44,.14),transparent 58%),linear-gradient(180deg,#0b0907,#050404)}
.screen-accuse::before{
  content:"";position:absolute;inset:0;pointer-events:none;z-index:0;
  background:repeating-linear-gradient(0deg,transparent 0 34px,rgba(0,0,0,.22) 34px 48px);
  transform:rotate(-7deg) scale(1.5);opacity:.35;mix-blend-mode:multiply;
}
.screen-accuse>*{position:relative;z-index:1}
.accuse-head{margin-top:clamp(12px,2.8vh,24px);margin-bottom:10px;flex-shrink:0}
.accuse-head h2{font-family:var(--serif);font-weight:900;font-size:clamp(30px,4.8vh,40px);line-height:.98;letter-spacing:-.03em;margin-top:4px;color:var(--paper-bright)}
.accuse-head p{margin-top:7px;max-width:34ch;font-family:var(--type);font-size:9.5px;line-height:1.45;color:var(--paper-dim)}
.accuse-list{flex:1;min-height:0;display:flex;flex-direction:column;justify-content:center;gap:6px}
.accuse-row{
  display:flex;align-items:center;gap:9px;width:100%;padding:7px 8px;text-align:left;
  background:linear-gradient(100deg,rgba(35,28,21,.88),rgba(16,13,10,.92));
  border:1px solid rgba(233,221,196,.13);transition:.22s;position:relative;
}
.accuse-row .mugshot{width:42px;height:54px;flex-basis:42px}
.accuse-row.selected{border-color:var(--gold-bright);background:linear-gradient(100deg,rgba(70,54,32,.9),rgba(28,21,14,.96));box-shadow:0 0 0 1px rgba(201,161,94,.22),0 10px 26px rgba(0,0,0,.4)}
.accuse-row.selected::before{content:"";position:absolute;left:-1px;top:8%;bottom:8%;width:2px;background:var(--gold-bright)}
.accuse-info{flex:1;min-width:0}
.accuse-top{display:flex;align-items:baseline;gap:7px;flex-wrap:wrap}
.accuse-name{font-family:var(--serif);font-size:clamp(15px,2.2vh,18px);font-weight:900;line-height:1;color:var(--paper-bright)}
.accuse-role{font-size:6px;letter-spacing:.15em;color:var(--gold);text-transform:uppercase;line-height:1.2}
.accuse-lines{margin-top:5px;display:flex;flex-direction:column;gap:2px}
.accuse-line{display:flex;gap:5px;font-family:var(--type);font-size:clamp(7.5px,1.03vh,9px);line-height:1.32;color:var(--paper-dim);min-width:0}
.accuse-line b{font-family:var(--ui);font-size:5.5px;letter-spacing:.13em;color:var(--paper-faint);font-weight:500;flex:0 0 38px;padding-top:2px}
.accuse-line span{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}
.accuse-pick{width:16px;height:16px;flex:0 0 16px;border:1px solid rgba(233,221,196,.26);border-radius:50%;display:grid;place-items:center;transition:.2s}
.accuse-pick::after{content:"";width:7px;height:7px;border-radius:50%;background:transparent;transition:.2s}
.accuse-row.selected .accuse-pick{border-color:var(--gold-bright)}
.accuse-row.selected .accuse-pick::after{background:var(--gold-bright);box-shadow:0 0 8px rgba(226,194,134,.7)}
.accuse-warning{
  flex-shrink:0;display:flex;align-items:center;justify-content:center;gap:6px;margin:6px 0;
  padding:6px 8px;border:1px solid rgba(141,42,42,.45);background:rgba(84,22,20,.18);
  font-size:6.5px;letter-spacing:.15em;color:#c98577;text-align:center;line-height:1.25;
}
.accuse-warning span{display:grid;place-items:center;width:12px;height:12px;border:1px solid rgba(201,133,119,.5);border-radius:50%;font-size:7px;flex-shrink:0}
.accuse-warning.safe{color:#b0a487;border-color:rgba(201,161,94,.35);background:rgba(80,62,34,.16)}
.accuse-warning.safe span{border-color:rgba(201,161,94,.5)}
#screen-accuse .btn-main{flex-shrink:0}
.screen-accuse.is-active .accuse-head{animation:riseIn .5s both}
.screen-accuse.is-active .accuse-row{animation:riseIn .45s both;animation-delay:calc(.08s + var(--i,0) * .06s)}
@keyframes riseIn{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}

/* ================= END SCREEN ================= */
.screen-end{
  background:
    radial-gradient(ellipse at 50% 30%,rgba(85,66,44,.16),transparent 52%),
    linear-gradient(180deg,#0b0908 0%,#060505 70%,#030303 100%);
  justify-content:flex-start;
}
.end-art{position:absolute;inset:0;z-index:0;overflow:hidden;pointer-events:none}
.end-glow{position:absolute;left:50%;top:20%;width:120%;height:70%;transform:translateX(-50%);background:radial-gradient(ellipse at 50% 40%,rgba(164,122,69,.14),transparent 62%)}
.end-blinds{
  position:absolute;left:-20%;top:-15%;width:140%;height:72%;
  background:repeating-linear-gradient(0deg,transparent 0 30px,rgba(0,0,0,.2) 30px 44px);
  transform:rotate(-9deg);opacity:.65;mix-blend-mode:multiply;
}
.end-art .rain{opacity:.22}
.end-floor{position:absolute;left:0;right:0;bottom:0;height:32%;background:linear-gradient(180deg,transparent,rgba(0,0,0,.6));border-top:1px solid rgba(233,221,196,.05)}
.screen-end.is-win .end-glow{background:radial-gradient(ellipse at 50% 38%,rgba(201,150,79,.22),rgba(94,43,30,.09) 40%,transparent 68%);animation:winGlow 4s ease-in-out infinite}
.screen-end.is-loss .end-glow{background:radial-gradient(ellipse at 50% 38%,rgba(94,119,129,.13),transparent 62%)}
@keyframes winGlow{0%,100%{opacity:.8}50%{opacity:1.25}}
.screen-end>*{position:relative;z-index:1}
.end-hud{align-items:center;padding-bottom:2px}
.end-weather{font-size:6.5px;letter-spacing:.18em;color:var(--paper-faint);text-transform:uppercase}
.verdict{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;min-height:0;padding:12px 0}
.stamp{
  display:inline-block;padding:6px 13px;border:3px double currentColor;color:#a2493f;
  font-family:var(--ui);font-size:clamp(21px,3.2vh,28px);font-weight:600;letter-spacing:.16em;line-height:1;
  transform:rotate(-7deg);opacity:.9;text-indent:.16em;
  box-shadow:inset 0 0 18px rgba(162,73,63,.08);
  animation:endStamp .65s .15s cubic-bezier(.2,1.2,.4,1) both;
}
.screen-end.is-loss .stamp{color:#918779;box-shadow:none}
@keyframes endStamp{from{opacity:0;transform:scale(1.8) rotate(-14deg)}to{opacity:.9;transform:scale(1) rotate(-7deg)}}
.verdict h2{
  margin-top:16px;font-family:var(--serif);font-weight:900;font-size:clamp(29px,4.8vh,39px);
  line-height:.98;letter-spacing:-.03em;color:var(--paper-bright);max-width:11ch;text-wrap:balance;
}
.screen-end.is-loss .verdict h2{color:#ddd2bd}
.verdict p{
  margin-top:10px;max-width:30ch;font-family:var(--type);font-size:clamp(9.5px,1.3vh,11px);
  line-height:1.55;color:var(--paper-dim);
}
.end-card{
  flex-shrink:0;margin-bottom:10px;padding:10px 12px;border:1px solid rgba(233,221,196,.14);
  background:linear-gradient(180deg,rgba(24,19,14,.8),rgba(9,7,5,.92));
  box-shadow:0 16px 40px rgba(0,0,0,.5);backdrop-filter:blur(4px);
}
.end-row{display:flex;align-items:baseline;gap:10px;padding:4px 0;border-bottom:1px solid rgba(233,221,196,.07);line-height:1.2}
