  coat: { name: 'The coat', short: 'COAT', exhibit: 'C', plate: '03', place: "In the coat's lining", tag: 'the coat' },
  safe: { name: 'The safe', short: 'SAFE', exhibit: 'D', plate: '04', place: "Inside the safe's dial", tag: 'the safe' }
};

