.accuse-pick::after{content:"";width:7px;height:7px;border-radius:50%;background:transparent;transition:.2s}
.accuse-row.selected .accuse-pick{border-color:var(--gold-bright)}
.accuse-row.selected .accuse-pick::after{background:var(--gold-bright);box-shadow:0 0 8px rgba(226,194,134,.7)}
.accuse-warning{
  flex-shrink:0;display:flex;align-items:center;justify-content:center;gap:6px;margin:6px 0;
  padding:6px 8px;border:1px solid rgba(141,42,42,.45);background:rgba(84,22,20,.18);
  font-size:6.5px;letter-spacing:.15em;color:#c98577;text-align:center;line-height:1.25;
}
.accuse-warning span{display:grid;place-items:center;width:12px;height:12px;border:1px solid rgba(201,133,119,.5);border-radius:50%;font-size:7px;flex-shrink:0}
.accuse-warning.safe{color:#b0a487;border-color:rgba(201,161,94,.35);background:rgba(80,62,34,.16)}
