@keyframes riseIn{from{opacity:0;transform:translateY(9px)}to{opacity:1;transform:translateY(0)}}

/* ================= END SCREEN ================= */
.screen-end{
  background:
    radial-gradient(ellipse at 50% 30%,rgba(85,66,44,.16),transparent 52%),
