.end-blinds{
  position:absolute;left:-20%;top:-15%;width:140%;height:72%;
  background:repeating-linear-gradient(0deg,transparent 0 30px,rgba(0,0,0,.2) 30px 44px);
  transform:rotate(-9deg);opacity:.65;mix-blend-mode:multiply;
}
.end-art .rain{opacity:.22}
.end-floor{position:absolute;left:0;right:0;bottom:0;height:32%;background:linear-gradient(180deg,transparent,rgba(0,0,0,.6));border-top:1px solid rgba(233,221,196,.05)}
.screen-end.is-win .end-glow{background:radial-gradient(ellipse at 50% 38%,rgba(201,150,79,.22),rgba(94,43,30,.09) 40%,transparent 68%);animation:winGlow 4s ease-in-out infinite}
.screen-end.is-loss .end-glow{background:radial-gradient(ellipse at 50% 38%,rgba(94,119,129,.13),transparent 62%)}
@keyframes winGlow{0%,100%{opacity:.8}50%{opacity:1.25}}
.screen-end>*{position:relative;z-index:1}
.end-hud{align-items:center;padding-bottom:2px}
.end-weather{font-size:6.5px;letter-spacing:.18em;color:var(--paper-faint);text-transform:uppercase}
.verdict{flex:1;display:flex;flex-direction:column;justify-content:center;align-items:center;text-align:center;min-height:0;padding:12px 0}
.stamp{
