cat > /tmp/opencode/pw/test.js <<'EOF'
const { chromium } = require('playwright');
(async() => {
  const browser = await chromium.launch();
  for (const [w,h] of [[390,844],[360,640],[430,932]]) {
    const page = await browser.newPage({ viewport:{width:w,height:h}, deviceScaleFactor:2 });
    await page.goto('http://localhost:8080/index.html');
    await page.waitForTimeout(600);
    await page.evaluate(() => {
      const m = window.__midnight;
      m.startCase();
      const c = m.state.caseData;
      // find gun clue and mark found along with all clues
      const gun = Object.values(c.clues).find(x => x.type === 'gun');
      m.state.found.add(gun.object);
      m.showEnd(true);
    });
    await page.waitForTimeout(900);
    await page.screenshot({ path:`/tmp/opencode/shots/v-win-${w}x${h}.png` });
    const dims = await page.evaluate(() => {
      const q = s => { const e=document.querySelector(s); const r=e.getBoundingClientRect(); return {s,top:Math.round(r.top),bottom:Math.round(r.bottom),h:Math.round(r.height),w:Math.round(r.width),font:getComputedStyle(e).fontSize}; };
      return { vh:innerHeight, vw:innerWidth, sc:document.querySelector('#screen-end').scrollHeight, ch:document.querySelector('#screen-end').clientHeight,
        els:['.end-hud','.verdict','#endStamp','#verdictFigure','.verdict h2','.verdict p','.end-card','#btnNewCase'].map(q) };
    });
    console.log(w+'x'+h, JSON.stringify(dims));
    // loss
    await page.evaluate(() => { window.__midnight.state.failure='wrong'; window.__midnight.showEnd(false); });
    await page.waitForTimeout(900);
    await page.screenshot({ path:`/tmp/opencode/shots/v-loss-${w}x${h}.png` });
    await page.close();
  }
  await browser.close();
})();
EOF
cd /tmp/opencode/pw && node test.js

