async function fit(page, label) {
  const bad = await page.evaluate(() => {
    const active = document.querySelector('.screen.is-active');
    const r = active.getBoundingClientRect();
    const out = [];
    for (const el of active.querySelectorAll('button, h1, h2, h3, p, .call-card, .clue-sheet, .board-body, .end-card, .verdict-figure')) {
      if (!el.offsetParent && getComputedStyle(el).position !== 'fixed') continue;
      const b = el.getBoundingClientRect();
      if (b.height > 0 && (b.bottom > innerHeight + 1 || b.top < -1)) out.push({ tag: el.tagName, cls: el.className, id: el.id, top: Math.round(b.top), bottom: Math.round(b.bottom) });
    }
    const scroll = [...active.querySelectorAll('*')].filter(e => e.scrollHeight > e.clientHeight + 2 && getComputedStyle(e).overflow === 'visible').length;
    return { screen: active.id, out, scroll, scrollH: active.scrollHeight, clientH: active.clientHeight };
  });
  if (bad.out.length || bad.scrollH > bad.clientH + 2) console.log('FIT', label, JSON.stringify(bad));
  else console.log('FIT OK', label, bad.screen);
}

